      INTEGER FUNCTION NV(TYPE)CC     RETURNS NUMBER OF VARIABLE PARAMETERS FOR A GIVEN ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'NELMS.CIN'CC     LOCAL VARIABLESC      INTEGER         TYPE      EXTERNAL        IDATAC-------------------------------------------------------C      NV = NELMS(TYPE)C       IF (TYPE .EQ. 1 .AND. NORD3 .EQ. 1) NV = 14      IF (TYPE .EQ. 1 .AND. NORD3 .GT. 1) NV = 0      IF (TYPE .EQ. 2) NV = NV + 1C      IF (TYPE .EQ. 6 .AND. TYPEC .EQ. 8) THEN        NV = 6        IF (NORD3 .GT. 1) NV = 0      ENDIFC      IF (TYPE .EQ. 8) THEN        NV = 6        IF (NORD3 .GT. 1) NV = 0      ENDIFC      IF (TYPE .EQ. 12 .AND. NORD3 .GT. 1) NV = 0      IF (TYPE .EQ. 13 .OR. TYPE .EQ. 16) NV = 0      IF (TYPE .EQ. 13 .AND. CDB .EQ. 9) NV = NV3      IF (TYPE .EQ. 14) NV = 6      IF (TYPE .EQ. 15) NV = 0C      IF (TYPE .EQ. 16) THEN        NV = 0        IF (NPARS .EQ. 1 .OR. NPARS .EQ. 12 .OR. NPARS .EQ. 13     1     .OR. (NPARS .GE. 16 .AND. NPARS .LE. 20)     2     .OR. (NPARS .GE. 22 .AND. NPARS .LE. 25)) NV = 2      ENDIFC      IF (TYPE .EQ. 20 .AND. REFER) NV = 0      IF (TYPE .EQ. 38) NV = 0C      RETURN      END